import sys
from collections import defaultdict, deque

def bfs(tree, start):
    dist = {start: 0}
    queue = deque([start])
    while queue:
        node = queue.popleft()
        for neighbor in tree[node]:
            if neighbor not in dist:
                dist[neighbor] = dist[node] + 1
                queue.append(neighbor)
    return dist

def lca(tree, root, node1, node2):
    parent = {root: None}
    def dfs(node, par):
        parent[node] = par
        for neighbor in tree[node]:
            if neighbor != par:
                dfs(neighbor, node)
    dfs(root, None)

    path1 = set()
    while node1 is not None:
        path1.add(node1)
        node1 = parent[node1]

    while node2 not in path1:
        node2 = parent[node2]

    return node2

def main():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    n = int(input[idx])
    m = int(input[idx + 1])
    idx += 2
    roads = []
    for _ in range(n - 1):
        v = int(input[idx])
        u = int(input[idx + 1])
        roads.append((v, u))
        idx += 2
    citizens = []
    for _ in range(m):
        xi = int(input[idx])
        yi = int(input[idx + 1])
        citizens.append((xi, yi))
        idx += 2

    tree = defaultdict(list)
    for v, u in roads:
        tree[v].append(u)
        tree[u].append(v)

    root = 1
    dist_from_root = bfs(tree, root)

    paths = []
    for xi, yi in citizens:
        path = set()
        current = xi
        while current != yi:
            path.add(current)
            if dist_from_root[current] < dist_from_root[yi]:
                current = next(neighbor for neighbor in tree[current] if neighbor in dist_from_root and dist_from_root[neighbor] == dist_from_root[current] + 1)
            else:
                current = next(neighbor for neighbor in tree[current] if neighbor in path)
        path.add(yi)
        paths.append(path)

    guardians = set()
    for path in paths:
        for v, u in roads:
            if v in path and u in path:
                guardians.add((min(v, u), max(v, u)))

    citizens_with_puppies = set()
    for i, (xi, yi) in enumerate(citizens):
        if xi in paths[i] and yi in paths[i]:
            citizens_with_puppies.add(i + 1)

    guardians_with_puppies = set()
    for i, (v, u) in enumerate(roads):
        if (v, u) in guardians:
            guardians_with_puppies.add(i + 1)

    k = len(citizens_with_puppies) + len(guardians_with_puppies)
    print(k)
    print(len(citizens_with_puppies), *citizens_with_puppies)
    print(len(guardians_with_puppies), *guardians_with_puppies)

if __name__ == "__main__":
    main()
